COPY public.page_page (id, slug, title, content, created_at, is_published, published_at, seo_description, seo_title, metadata, private_metadata, page_type_id, search_index_dirty, search_vector) FROM stdin;
3	about	About	{"time": 1652791943847, "blocks": [{"id": "1rqw8KEYBR", "data": {"text": "1 Saleor is a rapidly growing all-out commerce API. Saleor is <b>fully open-source, and 100% focused on the GraphQL</b>&nbsp;interface. Our mission is to provide unparalleled extensibility."}, "type": "paragraph"}, {"id": "Is0DQGyb93", "data": {"text": "2 We make it easy for front-end teams to <b>prototype fast, experiment, and build wonderful, unrestricted storefront experiences</b>."}, "type": "paragraph"}, {"id": "IwwtFzGF2A", "data": {"text": "3 We enable developers to <a href=\\"https://docs.saleor.io/developer/extending/apps/overview\\" rel=\\"noopener noreferrer\\">extend Saleor</a> easily via [Saleor Apps](https://github.com/saleor/saleor-app-template), a robust tally of async/sync webhooks, and a composable Dashboard. "}, "type": "paragraph"}, {"id": "lJNRLN33D3", "data": {"text": "4 We allow brands to own their data and go fast while staying fully flexible with <a href=\\"https://cloud.saleor.io\\" rel=\\"noopener noreferrer\\">Saleor Cloud</a>."}, "type": "paragraph"}], "version": "2.22.2"}	2022-05-13 16:45:57.101+00	t	2022-05-13 00:00:00+00			{}	{}	4	t	\N
4	frutello	Frutello	{"time": 1759136694252, "blocks": [{"id": "gQR87kggYT", "data": {"text": "<b>Frutello</b> was founded with a simple goal: to make everyday hydration refreshing, fun, and natural. We blend exotic fruits with bold flavors to bring you juices that spark energy and joy."}, "type": "paragraph"}], "version": "2.30.7"}	2025-09-25 08:55:21+00	t	2025-09-25 09:55:21+00			{}	{}	5	t	\N
5	saleor-loom	Saleor Loom	{"time": 1760423902356, "blocks": [{"id": "-6od1Tl3ok", "data": {"text": "Saleor Loom is a creative studio redefining comfort wear. Every piece is designed with mindful craftsmanship - from breathable organic fabrics to urban-inspired silhouettes. Our mission? To make fashion that moves with you, not against you."}, "type": "paragraph"}], "version": "2.30.7"}	2025-10-14 06:38:16+00	t	2025-10-14 06:38:16+00			{}	{}	5	t	\N
6	cozynest	CozyNest	{"time": 1760423902356, "blocks": [{"id": "O6Yitsup5b", "data": {"text": "At CozyNest, we believe every home tells a story - one of warmth, comfort, and personality. Our textiles and decor are crafted to make your favorite spaces feel inviting, calm, and beautifully lived-in."}, "type": "paragraph"}], "version": "2.30.7"}	2025-10-14 06:38:16+00	t	2025-10-14 06:38:16+00			{}	{}	5	t	\N
